import { EgradxApiError } from '@babulvaibhav/egradx-client'

/*
 * Shared by the EGRADX recipes (shadcn registry items from @babulvaibhav/egradx-ui). Copied into your project like the rest of
 * a recipe: change the wording, the formats or the colours here and every recipe follows.
 */

/** Something to tell the person: wire it to your toasts (`sonner`'s `toast[tone](title, { description })`). */
export type Notify = (message: { tone: 'success' | 'info' | 'warning' | 'error'; title: string; description?: string }) => void

/** Used when a recipe is given no `onNotify`: messages are dropped, the screens still show errors inline. */
export const ignoreNotice: Notify = () => {}

/** Badge colours by meaning, for `<Badge variant="outline" className={tone.success}>`. */
export const tone = {
  success: 'border-emerald-500/30 bg-emerald-500/10 text-emerald-700 dark:text-emerald-400',
  warning: 'border-amber-500/30 bg-amber-500/10 text-amber-700 dark:text-amber-400',
  info: 'border-sky-500/30 bg-sky-500/10 text-sky-700 dark:text-sky-400',
  danger: 'border-destructive/30 bg-destructive/10 text-destructive',
  muted: 'text-muted-foreground',
} as const

const dateTime = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' })
const relative = new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' })

export function formatDateTime(iso: string | null | undefined): string {
  return iso ? dateTime.format(new Date(iso)) : '—'
}

/** "3 minutes ago", "in 2 hours". */
export function formatRelative(iso: string | null | undefined): string {
  if (!iso) return '—'
  const seconds = (new Date(iso).getTime() - Date.now()) / 1000
  const units: [Intl.RelativeTimeFormatUnit, number][] = [['year', 31536000], ['month', 2592000], ['day', 86400], ['hour', 3600], ['minute', 60]]
  for (const [unit, size] of units) {
    if (Math.abs(seconds) >= size) return relative.format(Math.round(seconds / size), unit)
  }
  return relative.format(Math.round(seconds), 'second')
}

/** `oim.product_updated` → "Oim product updated". */
export function humanize(value: string | null | undefined): string {
  if (!value) return ''
  const words = value.replace(/[._-]+/g, ' ').trim().toLowerCase()
  return words.charAt(0).toUpperCase() + words.slice(1)
}

export function shortId(id: string): string {
  return id.slice(0, 8)
}

/** A channel id as people read it. Unknown ids, added by configuration, are shown as they are. */
export function channelLabel(id: string): string {
  const labels: Record<string, string> = { email: 'Email', sms: 'SMS', whatsapp: 'WhatsApp', slack: 'Slack', webhook: 'Webhook', log: 'Log' }
  return labels[id] ?? id
}

/** What went wrong, to show the person: the server's message, or a plain one. */
export function errorText(error: unknown): string {
  if (error instanceof EgradxApiError) {
    if (error.code === 'NETWORK_ERROR') return 'The server could not be reached. Check your connection and try again.'
    if (error.code === 'ACCESS_DENIED') return 'You do not have permission to do this.'
    return error.message
  }
  return error instanceof Error ? error.message : 'Something went wrong.'
}

export function errorCode(error: unknown): string | undefined {
  return error instanceof EgradxApiError ? error.code : undefined
}

'use client'

import { useEffect, useState, type ReactNode } from 'react'
import { Inbox, LoaderCircle, RefreshCw, Search, ShieldAlert, TriangleAlert, X } from 'lucide-react'
import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { cn } from '@/lib/utils'
import { errorCode, errorText } from './egradx-ui'

/* The small pieces every EGRADX recipe shares: empty and error states, a confirmation, a search box. */

interface StateProps {
  icon?: ReactNode
  title: ReactNode
  description?: ReactNode
  action?: ReactNode
  className?: string
}

export function EmptyState({ icon = <Inbox />, title, description, action, className }: StateProps) {
  return (
    <div className={cn('flex flex-col items-center justify-center gap-3 px-6 py-12 text-center', className)}>
      <div className="bg-muted text-muted-foreground flex size-12 items-center justify-center rounded-full [&_svg]:size-5">{icon}</div>
      <div className="space-y-1">
        <p className="font-medium">{title}</p>
        {description && <p className="text-muted-foreground mx-auto max-w-sm text-sm">{description}</p>}
      </div>
      {action}
    </div>
  )
}

/** A failed load: "not allowed" for a refusal, otherwise what went wrong, with a retry. */
export function ErrorState({ error, onRetry, className }: { error: unknown; onRetry?: () => void; className?: string }) {
  if (errorCode(error) === 'ACCESS_DENIED') {
    return (
      <EmptyState
        className={className}
        icon={<ShieldAlert />}
        title="Access restricted"
        description="Your role does not include this. Ask an administrator if you need it."
      />
    )
  }
  return (
    <EmptyState
      className={className}
      icon={<TriangleAlert className="text-destructive" />}
      title="Couldn't load this"
      description={errorText(error)}
      action={
        onRetry && (
          <Button variant="outline" size="sm" onClick={onRetry}>
            <RefreshCw /> Try again
          </Button>
        )
      }
    />
  )
}

interface ConfirmDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  title: ReactNode
  description?: ReactNode
  confirmLabel?: string
  destructive?: boolean
  pending?: boolean
  onConfirm: () => void
}

/** Asks before something that cannot be undone; stays open until the change is done. */
export function ConfirmDialog({ open, onOpenChange, title, description, confirmLabel = 'Confirm', destructive, pending, onConfirm }: ConfirmDialogProps) {
  return (
    <AlertDialog open={open} onOpenChange={(next) => !pending && onOpenChange(next)}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>{title}</AlertDialogTitle>
          {description && <AlertDialogDescription>{description}</AlertDialogDescription>}
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel disabled={pending}>Cancel</AlertDialogCancel>
          <Button variant={destructive ? 'destructive' : 'default'} disabled={pending} onClick={onConfirm}>
            {pending && <LoaderCircle className="animate-spin" />}
            {confirmLabel}
          </Button>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

/** A search box that reports what was typed once typing pauses. */
export function SearchBox({ value, onChange, placeholder = 'Search…', className }: { value: string; onChange: (value: string) => void; placeholder?: string; className?: string }) {
  const [draft, setDraft] = useState(value)
  useEffect(() => setDraft(value), [value])
  useEffect(() => {
    if (draft.trim() === value) return
    const timer = setTimeout(() => onChange(draft.trim()), 300)
    return () => clearTimeout(timer)
    // Only typing starts the timer.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [draft])
  return (
    <div className={cn('relative w-full sm:w-72', className)}>
      <Search className="text-muted-foreground pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2" />
      <Input value={draft} onChange={(event) => setDraft(event.target.value)} placeholder={placeholder} aria-label={placeholder} className="pr-8 pl-9" />
      {draft && (
        <button
          type="button"
          onClick={() => setDraft('')}
          className="text-muted-foreground hover:text-foreground absolute top-1/2 right-2 -translate-y-1/2 rounded p-0.5"
          aria-label="Clear search"
        >
          <X className="size-3.5" />
        </button>
      )}
    </div>
  )
}

import { acceptList } from '@babulvaibhav/egradx-client'
import { errorCode, errorText } from '../egradx-ui'

/* The files recipes' wording and formats. Change them here and the upload, attachments and avatar recipes follow. */

const sizeFormat = new Intl.NumberFormat(undefined, { maximumFractionDigits: 1 })

/** 1536 → "1.5 KB". */
export function formatFileSize(bytes: number | null | undefined): string {
  if (bytes === null || bytes === undefined) return '—'
  const units = ['bytes', 'KB', 'MB', 'GB']
  let value = bytes
  let unit = 0
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024
    unit += 1
  }
  return unit === 0 ? `${bytes} ${bytes === 1 ? 'byte' : 'bytes'}` : `${sizeFormat.format(value)} ${units[unit]}`
}

const FAMILIES: Record<string, string> = { 'image/*': 'images', 'video/*': 'videos', 'audio/*': 'audio', 'text/*': 'text files' }
const TYPES: Record<string, string> = {
  'application/pdf': 'PDF',
  'image/png': 'PNG',
  'image/jpeg': 'JPEG',
  'image/webp': 'WebP',
  'image/gif': 'GIF',
  'text/csv': 'CSV',
  'application/zip': 'ZIP',
}

/** `image/*, application/pdf` → "images or PDF". */
export function describeAccept(accept: string | readonly string[] | undefined): string {
  const names = acceptList(accept).map((rule) => FAMILIES[rule] ?? TYPES[rule] ?? (rule.startsWith('.') ? rule.slice(1).toUpperCase() : rule))
  const unique = [...new Set(names)]
  return unique.length <= 1 ? (unique[0] ?? '') : `${unique.slice(0, -1).join(', ')} or ${unique.at(-1)}`
}

/** Limits a screen shows and checks: what it accepts, and the largest size. */
export interface FileLimitsText {
  accept?: string | readonly string[]
  maxSize?: number
}

/** "PDF or images, up to 25 MB." — or nothing, when there are no limits to tell. */
export function limitsHint({ accept, maxSize }: FileLimitsText): string {
  const parts = [describeAccept(accept), maxSize ? `up to ${formatFileSize(maxSize)}` : ''].filter(Boolean)
  if (!parts.length) return ''
  const text = parts.join(', ')
  return `${text.charAt(0).toUpperCase()}${text.slice(1)}.`
}

/** What went wrong with a file, worded per code. The limits are the screen's, used when the refusal carries none. */
export function fileErrorText(error: unknown, limits: FileLimitsText = {}): string {
  const details = (error as { details?: { maxSize?: number } } | null)?.details
  switch (errorCode(error)) {
    case 'FILE_TOO_LARGE': {
      const max = details?.maxSize ?? limits.maxSize
      return max ? `The file is larger than ${formatFileSize(max)}.` : 'The file is too large.'
    }
    case 'FILE_TYPE_NOT_ALLOWED': {
      const allowed = describeAccept(limits.accept)
      return allowed ? `This type of file isn't allowed. Choose ${allowed}.` : "This type of file isn't allowed here."
    }
    case 'FILE_EMPTY':
      return 'The file is empty.'
    case 'FILE_REJECTED':
      return 'The file was refused by a safety check.'
    case 'FILE_STORAGE_UNAVAILABLE':
      return "Files can't be stored right now. Try again in a moment."
    case 'NOT_FOUND':
      return 'The file no longer exists.'
    case 'ACCESS_DENIED':
      return "You don't have permission to do this."
    default:
      return errorText(error)
  }
}

/** Two letters for an avatar without a photo: "Ada Lovelace" → "AL". */
export function initialsOf(name: string | null | undefined): string {
  const words = (name ?? '').trim().split(/[\s@._-]+/).filter(Boolean)
  return ((words[0]?.[0] ?? '') + (words.length > 1 ? (words.at(-1)?.[0] ?? '') : '')).toUpperCase() || '?'
}

'use client'

import { useRef, useState, type ReactNode } from 'react'
import { LoaderCircle, Upload, X } from 'lucide-react'
import type { EgradxFile } from '@babulvaibhav/egradx-client'
import { useFileUpload } from '@babulvaibhav/egradx-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'
import { ignoreNotice, type Notify } from '../egradx-ui'
import { fileErrorText, limitsHint } from './file-format'

export interface FileUploadProps {
  /** `attachment` when left out. */
  purpose?: string
  /** The record the files belong to: both or neither. */
  attachedType?: string
  attachedId?: string
  /**
   * What may be chosen, as `<input accept>` takes it (`image/*,application/pdf`). Checked before sending, with the
   * server's wording; keep it in step with the server's `egradx.files.allowed-content-types`.
   */
  accept?: string
  /** The largest file in bytes, checked before sending. Keep it in step with the server's `egradx.files.max-size`. */
  maxSize?: number
  /** Several files at once, uploaded one after another. */
  multiple?: boolean
  disabled?: boolean
  /** Called with each file stored. */
  onUploaded?: (file: EgradxFile) => void
  onNotify?: Notify
  /** The drop zone's words. */
  label?: ReactNode
  /** Under the label. Default: the limits, e.g. "Images or PDF, up to 25 MB." */
  hint?: ReactNode
  /** A single row instead of a tall drop zone, e.g. above a list. */
  compact?: boolean
  className?: string
}

/** A drop zone and a button: uploads with progress and cancel, and says why a file was refused. */
export function FileUpload({
  purpose,
  attachedType,
  attachedId,
  accept,
  maxSize,
  multiple,
  disabled,
  onUploaded,
  onNotify = ignoreNotice,
  label,
  hint,
  compact,
  className,
}: FileUploadProps) {
  const input = useRef<HTMLInputElement>(null)
  const [dragging, setDragging] = useState(false)
  const [current, setCurrent] = useState<string | null>(null)
  const upload = useFileUpload({ purpose, attachedType, attachedId, accept, maxSize, onUploaded })
  const busy = upload.uploading || current !== null

  async function send(files: File[]) {
    if (!files.length) return
    upload.reset()
    for (const file of multiple ? files : files.slice(0, 1)) {
      setCurrent(file.name)
      try {
        const stored = await upload.upload(file)
        onNotify({ tone: 'success', title: 'Uploaded', description: stored.name })
      } catch (error) {
        // Cancelled: stop here, quietly. Refused: the message is shown below; go on with the next.
        if ((error as { name?: string }).name === 'AbortError') break
      }
    }
    setCurrent(null)
  }

  const percent = Math.round((upload.progress?.fraction ?? 0) * 100)
  const hintText = hint ?? limitsHint({ accept, maxSize })

  return (
    <div className={cn('space-y-2', className)}>
      <div
        onDragOver={(event) => {
          if (disabled || busy) return
          event.preventDefault()
          setDragging(true)
        }}
        onDragLeave={() => setDragging(false)}
        onDrop={(event) => {
          event.preventDefault()
          setDragging(false)
          if (!disabled && !busy) void send([...event.dataTransfer.files])
        }}
        className={cn(
          'border-input flex rounded-lg border border-dashed transition-colors',
          compact ? 'items-center gap-3 px-3 py-2' : 'flex-col items-center justify-center gap-2 px-6 py-8 text-center',
          dragging && 'border-primary bg-primary/5',
          (disabled || busy) && 'opacity-80',
        )}
      >
        {busy ? (
          <div className={cn('w-full space-y-2', compact && 'flex items-center gap-3 space-y-0')} aria-live="polite">
            <div className={cn('flex items-center gap-2 text-sm', !compact && 'justify-center')}>
              <LoaderCircle className="size-4 shrink-0 animate-spin" />
              <span className="truncate">Uploading {current}…</span>
              <span className="text-muted-foreground tabular-nums">{percent}%</span>
            </div>
            <div
              className={cn('bg-muted h-1.5 overflow-hidden rounded-full', compact ? 'min-w-24 flex-1' : 'mx-auto w-full max-w-xs')}
              role="progressbar"
              aria-valuemin={0}
              aria-valuemax={100}
              aria-valuenow={percent}
              aria-label={`Uploading ${current ?? ''}`}
            >
              <div className="bg-primary h-full transition-[width]" style={{ width: `${percent}%` }} />
            </div>
            <Button type="button" variant="ghost" size="sm" onClick={upload.cancel}>
              <X /> Cancel
            </Button>
          </div>
        ) : (
          <>
            {!compact && (
              <div className="bg-muted text-muted-foreground flex size-10 items-center justify-center rounded-full">
                <Upload className="size-4" />
              </div>
            )}
            <div className={cn('min-w-0', compact && 'flex-1')}>
              <p className="text-sm font-medium">{label ?? (multiple ? 'Drop files here' : 'Drop a file here')}</p>
              {hintText && <p className="text-muted-foreground text-xs">{hintText}</p>}
            </div>
            <Button type="button" size="sm" variant={compact ? 'outline' : 'default'} disabled={disabled} onClick={() => input.current?.click()}>
              <Upload /> {multiple ? 'Choose files' : 'Choose a file'}
            </Button>
          </>
        )}
        <input
          ref={input}
          type="file"
          className="sr-only"
          tabIndex={-1}
          accept={accept}
          multiple={multiple}
          disabled={disabled}
          onChange={(event) => {
            const files = [...(event.target.files ?? [])]
            // The same file again must fire a change.
            event.target.value = ''
            void send(files)
          }}
        />
      </div>
      {upload.error && (
        <p role="alert" className="text-destructive text-sm">
          {fileErrorText(upload.error, { accept, maxSize })}
        </p>
      )}
    </div>
  )
}

'use client'

import { useState, type ReactNode } from 'react'
import { Download, File as FileIcon, FileImage, FileSpreadsheet, FileText, LoaderCircle, Paperclip, Trash2 } from 'lucide-react'
import type { EgradxFile } from '@babulvaibhav/egradx-client'
import { useAction, useAttachments } from '@babulvaibhav/egradx-react'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import { cn } from '@/lib/utils'
import { ConfirmDialog, EmptyState, ErrorState } from '../egradx-common'
import { formatDateTime, formatRelative, ignoreNotice, type Notify } from '../egradx-ui'
import { FileUpload } from './file-upload'
import { fileErrorText, formatFileSize } from './file-format'

export interface AttachmentsProps {
  /** The record the files belong to: an application's own type and id, e.g. `order` and the order's id. */
  attachedType: string
  attachedId: string
  title?: ReactNode
  description?: ReactNode
  /** What may be uploaded and how large, checked before sending (see FileUpload). */
  accept?: string
  maxSize?: number
  /** Show the upload. Default true; the server still decides. */
  canUpload?: boolean
  /** Show delete, for every file or per file. Default true; the server still decides. */
  canDelete?: boolean | ((file: EgradxFile) => boolean)
  onNotify?: Notify
  className?: string
}

function iconFor(contentType: string) {
  if (contentType.startsWith('image/')) return <FileImage />
  if (contentType === 'application/pdf' || contentType.startsWith('text/')) return <FileText />
  if (contentType.includes('spreadsheet') || contentType.includes('excel') || contentType === 'text/csv') return <FileSpreadsheet />
  return <FileIcon />
}

/** A record's files: name, size and date, download, delete, and an upload above the list. */
export function Attachments({
  attachedType,
  attachedId,
  title = 'Attachments',
  description,
  accept,
  maxSize,
  canUpload = true,
  canDelete = true,
  onNotify = ignoreNotice,
  className,
}: AttachmentsProps) {
  const attachments = useAttachments({ attachedType, attachedId })
  const [removing, setRemoving] = useState<EgradxFile | null>(null)
  const [downloading, setDownloading] = useState<string | null>(null)

  const remove = useAction(async (file: EgradxFile) => {
    try {
      await attachments.remove(file.id)
      setRemoving(null)
      onNotify({ tone: 'success', title: 'File deleted', description: file.name })
    } catch (error) {
      onNotify({ tone: 'error', title: 'Could not delete the file', description: fileErrorText(error) })
    }
  })

  async function download(file: EgradxFile) {
    setDownloading(file.id)
    try {
      await attachments.download(file)
    } catch (error) {
      onNotify({ tone: 'error', title: 'Could not download the file', description: fileErrorText(error) })
    } finally {
      setDownloading(null)
    }
  }

  const deletable = (file: EgradxFile) => (typeof canDelete === 'function' ? canDelete(file) : canDelete)

  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Paperclip className="size-4" /> {title}
          {attachments.files.length > 0 && <span className="text-muted-foreground text-sm font-normal">({attachments.files.length})</span>}
        </CardTitle>
        {description && <CardDescription>{description}</CardDescription>}
      </CardHeader>
      <CardContent className="space-y-4">
        {canUpload && (
          <FileUpload
            compact
            multiple
            attachedType={attachedType}
            attachedId={attachedId}
            accept={accept}
            maxSize={maxSize}
            onUploaded={() => void attachments.reload()}
            onNotify={onNotify}
          />
        )}
        {attachments.loading ? (
          <div className="space-y-2">
            <Skeleton className="h-10 w-full" />
            <Skeleton className="h-10 w-full" />
          </div>
        ) : attachments.error && !attachments.data ? (
          <ErrorState error={attachments.error} onRetry={() => void attachments.reload()} />
        ) : attachments.files.length === 0 ? (
          <EmptyState className="py-6" icon={<Paperclip />} title="No files yet" description={canUpload ? 'Files added here stay with this record.' : undefined} />
        ) : (
          <ul className="divide-y rounded-md border">
            {attachments.files.map((file) => (
              <li key={file.id} className="flex items-center gap-3 px-3 py-2">
                <span className="text-muted-foreground [&_svg]:size-4">{iconFor(file.contentType)}</span>
                <div className="min-w-0 flex-1">
                  <button
                    type="button"
                    className="block max-w-full truncate text-left text-sm font-medium hover:underline"
                    onClick={() => void download(file)}
                    title={file.name}
                  >
                    {file.name}
                  </button>
                  <p className="text-muted-foreground text-xs">
                    {formatFileSize(file.size)} · <time dateTime={file.createdAt} title={formatDateTime(file.createdAt)}>{formatRelative(file.createdAt)}</time>
                  </p>
                </div>
                <Button
                  size="icon"
                  variant="ghost"
                  aria-label={`Download ${file.name}`}
                  disabled={downloading === file.id}
                  onClick={() => void download(file)}
                >
                  {downloading === file.id ? <LoaderCircle className="animate-spin" /> : <Download />}
                </Button>
                {deletable(file) && (
                  <Button size="icon" variant="ghost" aria-label={`Delete ${file.name}`} onClick={() => setRemoving(file)}>
                    <Trash2 className={cn('text-muted-foreground')} />
                  </Button>
                )}
              </li>
            ))}
          </ul>
        )}
      </CardContent>
      <ConfirmDialog
        open={removing !== null}
        onOpenChange={(open) => !open && setRemoving(null)}
        title="Delete this file?"
        description={removing ? `${removing.name} is deleted for everyone. This cannot be undone.` : undefined}
        confirmLabel="Delete"
        destructive
        pending={remove.pending}
        onConfirm={() => removing && void remove.run(removing)}
      />
    </Card>
  )
}
